export function translate(value: string, language: Language): string {
  if (language === 'en') return value
  const trimmed = value.trim()
  const translation = hausa[trimmed]
  if (translation === undefined) return value
  const leading = value.match(/^\s*/)?.[0] ?? ''
  const trailing = value.match(/\s*$/)?.[0] ?? ''
  return `${leading}${translation}${trailing}`
}

type LanguageContextValue = {
  language: Language
  setLanguage: (language: Language) => void
}

const LanguageContext = createContext<LanguageContextValue>({
  language: 'en',
  setLanguage: () => undefined,
})

export function useLanguage() {
  return useContext(LanguageContext)
}

export function useTranslate() {
  const { language } = useLanguage()
  return (value: string) => translate(value, language)
}

export function LocalizedTree({ children }: { children: ReactNode }) {
  const { language } = useLanguage()
  return localizeNode(children, language)
}

function localizeNode(node: ReactNode, language: Language): ReactNode {
  if (typeof node === 'string') return translate(node, language)
  if (Array.isArray(node)) return Children.map(node, (child) => localizeNode(child, language))
  if (!isValidElement<Record<string, unknown>>(node)) return node

  const localizedProps: Record<string, unknown> = {}
  const children = node.props.children
  if (children !== undefined) localizedProps.children = localizeNode(children as ReactNode, language)

  for (const prop of ['alt', 'aria-label', 'aria-description', 'placeholder', 'title']) {
    const value = node.props[prop]
    if (typeof value === 'string') localizedProps[prop] = translate(value, language)
  }

  return cloneElement(node, localizedProps)
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>('en')
  useEffect(() => {
    try {
      const saved = window.localStorage.getItem(languageStorageKey)
      if (saved === 'en' || saved === 'ha') setLanguageState(saved)
    } catch {
      // The language remains usable for this session when storage is unavailable.
    }
  }, [])
  useEffect(() => {
    document.documentElement.lang = language
  }, [language])

  const setLanguage = (next: Language) => {
    setLanguageState(next)
    try {
      window.localStorage.setItem(languageStorageKey, next)
    } catch {
      // Keep the selection in memory if browser storage is unavailable.
    }
  }

  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      {localizeNode(Children.toArray(children), language)}
    </LanguageContext.Provider>
  )
}
